use thiserror::Error;

#[derive(Error, Debug)]
pub enum PaymentError {
    #[error("الرصيد غير كافٍ: المطلوب {required} سنت، المتاح فقط {available} سنت")]
    InsufficientFunds {
        required: u64,
        available: u64,
    },

    #[error("بوابة الدفع غير مستجيبة (انتهت المهلة بعد {0} ثواني)")]
    GatewayTimeout(u32),

    #[error("خطأ في قاعدة البيانات الداخلية")]
    DatabaseFailure(#[from] sqlx::Error), // تحويل sqlx::Error تلقائياً لـ PaymentError

    #[error("بيانات البطاقة غير صالحة: {0}")]
    InvalidCardData(String),
}

