use anyhow::{Context, Result};
use std::fs;

fn load_app_config(path: &str) -> Result<String> {
    let content = fs::read_to_string(path)
        .with_context(|| format!("فشل قراءة ملف الإعدادات من المسار: {}", path))?;

    Ok(content)
}

fn main() -> Result<()> {
    let config = load_app_config("/etc/myapp/config.toml")?;
    println!("تم تحميل الإعدادات بنجاح!");
    Ok(())
}
